def migrate_roles(apps, schema_editor):
    User = apps.get_model("accounts", "User")

    User.objects.filter(role="AGENT").update(role="CREDIT_AGENT")
    User.objects.filter(is_superuser=True).update(role="SUPERADMIN")


def reverse_roles(apps, schema_editor):
    User = apps.get_model("accounts", "User")

    User.objects.filter(role="CREDIT_AGENT").update(role="AGENT")
    User.objects.filter(role="SUPERADMIN").update(role="ADMIN")


